function getInitialState(){const urlParams=new URLSearchParams(window.location.search);let version=urlParams.get('version')||localStorage.getItem('redis-acl-builder-version')||'redis8';if(!['redis7','redis8'].includes(version)){console.warn(`Invalid version from URL/storage: ${version}, defaulting to redis8`);version='redis8';}
let mode=urlParams.get('mode')||localStorage.getItem('redis-acl-builder-mode')||'oss';if(!['oss','enterprise'].includes(mode)){console.warn(`Invalid mode from URL/storage: ${mode}, defaulting to oss`);mode='oss';}
if(urlParams.has('version')){localStorage.setItem('redis-acl-builder-version',version);}
if(urlParams.has('mode')){localStorage.setItem('redis-acl-builder-mode',mode);}
return{currentVersion:version,currentMode:mode,isLoading:false,debounceTimer:null};}
const AppState=getInitialState();AppState.update=function(updates){Object.assign(this,updates);if(updates.currentVersion){localStorage.setItem('redis-acl-builder-version',updates.currentVersion);}
if(updates.currentMode){localStorage.setItem('redis-acl-builder-mode',updates.currentMode);}};AppState.updateURL=function(version,mode){const url=new URL(window.location);url.searchParams.set('version',version);url.searchParams.set('mode',mode);window.history.replaceState({},'',url);};AppState.getAPIState=function(){return{version:this.currentVersion,mode:this.currentMode};};export default AppState;